void App::scroll(int code,int value){int next=scrollY;RECT r{};GetClientRect(viewport,&r);switch(code){case -1:next+=value;break;case SB_LINEUP:next-=px(hwnd,40);break;case SB_LINEDOWN:next+=px(hwnd,40);break;case SB_PAGEUP:next-=r.bottom;break;case SB_PAGEDOWN:next+=r.bottom;break;case SB_THUMBPOSITION:case SB_THUMBTRACK:next=value;break;case SB_TOP:next=0;break;case SB_BOTTOM:next=contentHeight;break;}scrollY=std::clamp(next,0,std::max(0,contentHeight-int(r.bottom)));pageLayout();}
void App::command(int id,int code){
    if(id>=11&&id<=13){activePage=id-11;scrollY=0;layout();return;}if(busy||scanning)return;
    if(id==10){int chosen=languageMenu(hwnd,langBox);if(chosen>=0)command(500+chosen,0);return;}if(id>=500&&id<=502){language=id-500;prefs["Language"]=language==0?"zh":language==1?"en":"ja";saveSettings(prefs);build();statusCheck();return;}
    if(id==23&&code==CBN_SELCHANGE){int n=int(SendMessageW(gameBox,CB_GETCURSEL,0,0));game=n>=0?games.at(size_t(n)):fs::path();if(!game.empty())lockGame();prefs["Game"]=utf8(game.wstring());saveSettings(prefs);statusCheck();return;}
    if(id==100){work([&]{inspect();});return;}if(id==101){auto paths=browse(hwnd,false,false);if(!paths.empty()){auto chosen=paths[0];if(lower(chosen.filename().wstring())!=L"sekiro.exe")throw Fault("noGame");game=chosen.parent_path();validateGame(game);lockGame();if(std::find(games.begin(),games.end(),game)==games.end())games.push_back(game);prefs["Game"]=utf8(game.wstring());saveSettings(prefs);build();}return;}
    if(id==102){work([&]{ready();if(!confirm(tr("engine"),tr("engineConfirm")))return;if(state(game).get("PauseEngine").boolean()&&!confirm(tr("engine"),tr("resume")))return;install(game,app/L"assets",{},false);if(!hasMods(game))message(tr("installed"),tr("emptyHint"));});return;}
    if(id==103){work([&]{ready();if(confirm(tr("restore"),tr("restoreConfirm")))restore(game,[&](auto& s){progress(s);});});return;}
    if(id==104){work([&]{ready();if(confirm(tr("clearMods"),tr("clearModsConfirm")))clearMods(game,[&](auto& s){progress(s);});ui([&]{activePage=0;layout();});});return;}
    if(id==105){statusCheck();return;}if(id==106||id==107){add(browse(hwnd,id==107,true));return;}if(id==108){inputs.clear();SendMessageW(inputList,LB_RESETCONTENT,0,0);return;}if(id==109){work([&]{localInstall();});return;}
    if(id==110||id==111){int i=int(SendMessageW(inputList,LB_GETCURSEL,0,0)),j=i+(id==110?-1:1);if(i>=0&&j>=0&&size_t(j)<inputs.size()){std::swap(inputs[size_t(i)],inputs[size_t(j)]);SendMessageW(inputList,LB_RESETCONTENT,0,0);for(auto& p:inputs)SendMessageW(inputList,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(p.c_str()));SendMessageW(inputList,LB_SETCURSEL,j,0);}return;}
    if(id==112){activePage=2;scrollY=0;layout();return;}if(id==113){shell(L"https://v.douyin.com/wmk_GI6325k/");return;}
    if(id>=200&&id<200+int(presets.size())*2){size_t index=size_t(id-200)/2;if((id-200)%2==0)work([this,index]{download(index);});else work([this,index]{presetInstall(index);});}
}
