    case WM_MEASUREITEM:{auto item=reinterpret_cast<MEASUREITEMSTRUCT*>(b);item->itemHeight=px(w,item->CtlType==ODT_MENU?36:28);if(item->CtlType==ODT_MENU)item->itemWidth=px(w,210);return TRUE;}case WM_DRAWITEM:{auto& item=*reinterpret_cast<DRAWITEMSTRUCT*>(b);if(self->qaMode&&item.CtlType==ODT_MENU&&item.itemID>=500&&item.itemID<=502)SetPropW(w,L"SMA.QaMenuDrawn",reinterpret_cast<HANDLE>(INT_PTR(GetPropW(w,L"SMA.QaMenuDrawn"))|(1<<(item.itemID-500))));drawButton(item);return TRUE;}
    case WM_MOUSEWHEEL:self->scroll(-1,-GET_WHEEL_DELTA_WPARAM(a)/WHEEL_DELTA*px(w,90));return 0;
    case invokeMessage:{std::unique_ptr<std::function<void()>> fn(reinterpret_cast<std::function<void()>*>(b));(*fn)();return 0;}
    case WM_APP+20:if(self->busy||self->scanning){SetTimer(w,2,100,nullptr);return 0;}PostMessageW(w,WM_CLOSE,0,0);return 0;
    case WM_TIMER:if(a==88){if(self->busy||self->scanning)return 0;KillTimer(w,88);self->qa();return 0;}if(a==2){if(!self->busy&&!self->scanning){KillTimer(w,2);PostMessageW(w,WM_CLOSE,0,0);}return 0;}self->network();if(!self->qaMode)self->statusCheck();return 0;
